const body = $input.first().json;
const phone = (body.sender || body.phone || '').replace(/[^0-9]/g, '');
const message = body.message || body.text || '';
const isMedia = !!(body.file || body.url);

if (!phone || !message) throw new Error('Invalid payload');

return [{ json: { phone, message, isMedia, mediaUrl: body.file || body.url || null } }];

const leads = $('Get Lead').all();
const incoming = $('Normalize Payload').first().json;
const isNew = leads.length === 0 || !leads[0].json.id;
const lead = isNew ? null : leads[0].json;

// Cek eskalasi dari pesan
const msg = incoming.message.toLowerCase();
const escalateWords = ['telepon','video call','komplain','kecewa','tipu','refund','tidak puas','marah','kembalikan uang'];
const shouldEscalate = escalateWords.some(w => msg.includes(w));

return [{ json: { isNew, lead, incoming, shouldEscalate } }];

const checkData = $('Check Lead').first().json;
const incoming = checkData.incoming;
let lead, history;

if (checkData.isNew) {
  lead = $('Create Lead').first().json;
  history = [];
} else {
  lead = checkData.lead;
  const rows = $('Get History').all();
  history = rows.map(r => ({ role: r.json.role, content: r.json.content }));
}

return [{ json: {
  leadId: lead.id,
  phone: incoming.phone,
  nama: lead.nama,
  stage: lead.stage,
  history,
  pesanBaru: incoming.message,
  shouldEscalate: checkData.shouldEscalate
}}];

const resp = $input.first().json;
const text = resp.content?.[0]?.text || 'Maaf, ada gangguan teknis. Mohon coba lagi.';
const ctx = $('Build Context').first().json;

// Deteksi stage dari respons
let newStage = ctx.stage;
const lowerText = text.toLowerCase();
if (lowerText.includes('audit') || lowerText.includes('kirim naskah')) newStage = 'Qualify';
if (lowerText.includes('paket') && lowerText.includes('rekomendasikan')) newStage = 'Paket Dipilih';

return [{ json: {
  leadId: ctx.leadId,
  phone: ctx.phone,
  reply: text,
  newStage,
  pesanUser: ctx.pesanBaru
}}];

const ctx = $('Build Context').first().json;
const ownerPhone = '628XXXXXXXXXXX'; // GANTI dengan nomor WA owner
const msg = `🚨 ESKALASI DIPERLUKAN

Lead: ${ctx.phone}
Nama: ${ctx.nama}
Stage: ${ctx.stage}

Pesan:
${ctx.pesanBaru}

Silakan hubungi langsung.`;

return [{ json: { ownerPhone, msg, leadPhone: ctx.phone } }];
